package parse

import (
	"net/mail"
	"reflect"
	"regexp"
	"strconv"
	"strings"

	"github.com/gravitational/trace"
)

// Expr is a typed, evaluable expression.
type Expr interface {
	String() string
	Kind() reflect.Kind
	Evaluate(EvaluateContext) (any, error)
}

// EvaluateContext supplies values for variables and input for match predicates.
type EvaluateContext struct {
	VarValue     func(VarExpr) ([]string, error)
	MatcherInput string
}

type StringLitExpr struct{ Value string }

func (e StringLitExpr) String() string                        { return strconv.Quote(e.Value) }
func (StringLitExpr) Kind() reflect.Kind                      { return reflect.String }
func (e StringLitExpr) Evaluate(EvaluateContext) (any, error) { return []string{e.Value}, nil }

type VarExpr struct{ Namespace, Name string }

func (e VarExpr) String() string   { return e.Namespace + "." + e.Name }
func (VarExpr) Kind() reflect.Kind { return reflect.String }
func (e VarExpr) Evaluate(ctx EvaluateContext) (any, error) {
	if ctx.VarValue != nil {
		return ctx.VarValue(e)
	}
	if e.Namespace == LiteralNamespace {
		return []string{e.Name}, nil
	}
	return nil, trace.BadParameter("no resolver for %s", e)
}

type EmailLocalExpr struct{ Input Expr }

func (e EmailLocalExpr) String() string   { return "email.local(" + e.Input.String() + ")" }
func (EmailLocalExpr) Kind() reflect.Kind { return reflect.String }
func (e EmailLocalExpr) Evaluate(ctx EvaluateContext) (any, error) {
	values, err := evalStrings(e.Input, ctx)
	if err != nil {
		return nil, err
	}
	out := make([]string, 0, len(values))
	for _, value := range values {
		if value == "" {
			return nil, trace.BadParameter("address is empty")
		}
		addr, err := mail.ParseAddress(value)
		if err != nil {
			return nil, trace.BadParameter("invalid email address %q: %v", value, err)
		}
		local, _, ok := strings.Cut(addr.Address, "@")
		if !ok || local == "" {
			return nil, trace.BadParameter("missing local part in %q", value)
		}
		out = append(out, local)
	}
	return out, nil
}

type RegexpReplaceExpr struct {
	Input                Expr
	Pattern, Replacement string
	re                   *regexp.Regexp
}

func (e RegexpReplaceExpr) String() string {
	return "regexp.replace(" + e.Input.String() + ", " + strconv.Quote(e.Pattern) + ", " + strconv.Quote(e.Replacement) + ")"
}
func (RegexpReplaceExpr) Kind() reflect.Kind { return reflect.String }
func (e RegexpReplaceExpr) Evaluate(ctx EvaluateContext) (any, error) {
	values, err := evalStrings(e.Input, ctx)
	if err != nil {
		return nil, err
	}
	re := e.re
	if re == nil {
		re, err = compileRegexp(e.Pattern)
		if err != nil {
			return nil, err
		}
	}
	var out []string
	for _, value := range values {
		if re.MatchString(value) {
			out = append(out, re.ReplaceAllString(value, e.Replacement))
		}
	}
	return out, nil
}

type RegexpMatchExpr struct {
	Pattern string
	re      *regexp.Regexp
}

func (e RegexpMatchExpr) String() string   { return "regexp.match(" + strconv.Quote(e.Pattern) + ")" }
func (RegexpMatchExpr) Kind() reflect.Kind { return reflect.Bool }
func (e RegexpMatchExpr) Evaluate(ctx EvaluateContext) (any, error) {
	re := e.re
	if re == nil {
		var err error
		re, err = compileRegexp(e.Pattern)
		if err != nil {
			return nil, err
		}
	}
	return re.MatchString(ctx.MatcherInput), nil
}

type RegexpNotMatchExpr struct {
	Pattern string
	re      *regexp.Regexp
}

func (e RegexpNotMatchExpr) String() string {
	return "regexp.not_match(" + strconv.Quote(e.Pattern) + ")"
}
func (RegexpNotMatchExpr) Kind() reflect.Kind { return reflect.Bool }
func (e RegexpNotMatchExpr) Evaluate(ctx EvaluateContext) (any, error) {
	re := e.re
	if re == nil {
		var err error
		re, err = compileRegexp(e.Pattern)
		if err != nil {
			return nil, err
		}
	}
	return !re.MatchString(ctx.MatcherInput), nil
}

func evalStrings(e Expr, ctx EvaluateContext) ([]string, error) {
	if e.Kind() != reflect.String {
		return nil, trace.BadParameter("expected string expression, got %s", e.Kind())
	}
	v, err := e.Evaluate(ctx)
	if err != nil {
		return nil, err
	}
	values, ok := v.([]string)
	if !ok {
		return nil, trace.BadParameter("expected string values from %s", e)
	}
	return values, nil
}
func compileRegexp(pattern string) (*regexp.Regexp, error) {
	re, err := regexp.Compile(pattern)
	if err != nil {
		return nil, trace.BadParameter("invalid regexp %q: %v", pattern, err)
	}
	return re, nil
}

func validateExpr(expr Expr) error {
	switch e := expr.(type) {
	case VarExpr:
		if e.Name == "" {
			return trace.BadParameter("incomplete variable %q: expected namespace.name", e.Namespace)
		}
	case EmailLocalExpr:
		return validateExpr(e.Input)
	case RegexpReplaceExpr:
		return validateExpr(e.Input)
	}
	return nil
}

package parse

import (
	"reflect"
	"strings"

	"github.com/gravitational/trace"
	"github.com/vulcand/predicate"

	"github.com/gravitational/teleport/lib/utils"
)

const (
	LiteralNamespace     = "literal"
	EmailNamespace       = "email"
	EmailLocalFnName     = "local"
	RegexpNamespace      = "regexp"
	RegexpMatchFnName    = "match"
	RegexpNotMatchFnName = "not_match"
	RegexpReplaceFnName  = "replace"
)

// Expression is a string expression with optional static text around it.
type Expression struct {
	expr           Expr
	prefix, suffix string
}

func (e *Expression) Namespace() string {
	if v, ok := e.expr.(VarExpr); ok {
		return v.Namespace
	}
	return ""
}
func (e *Expression) Name() string {
	if v, ok := e.expr.(VarExpr); ok {
		return v.Name
	}
	return ""
}

// Interpolate resolves every variable through traits and validates each reference.
func (e *Expression) Interpolate(traits map[string][]string, varValidation ...func(string, string) error) ([]string, error) {
	ctx := EvaluateContext{VarValue: func(v VarExpr) ([]string, error) {
		if len(varValidation) > 0 && varValidation[0] != nil {
			if err := varValidation[0](v.Namespace, v.Name); err != nil {
				return nil, trace.Wrap(err)
			}
		}
		if v.Namespace == LiteralNamespace {
			return []string{v.Name}, nil
		}
		values, ok := traits[v.Name]
		if !ok {
			return nil, trace.NotFound("variable %s is not found", v.String())
		}
		return values, nil
	}}
	values, err := evalStrings(e.expr, ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	out := make([]string, 0, len(values))
	for _, v := range values {
		if v != "" {
			out = append(out, e.prefix+v+e.suffix)
		}
	}
	if len(out) == 0 {
		return nil, trace.NotFound("variable interpolation produced no values")
	}
	return out, nil
}

func splitTemplate(input string) (prefix, body, suffix string, braced bool, err error) {
	input = strings.TrimSpace(input)
	start := strings.Index(input, "{{")
	if start < 0 {
		if strings.ContainsAny(input, "{}") {
			return "", "", "", false, trace.BadParameter("malformed template usage %q: expected {{expression}}", input)
		}
		return "", input, "", false, nil
	}
	if strings.ContainsAny(input[:start], "{}") {
		return "", "", "", false, trace.BadParameter("malformed template usage %q: expected {{expression}}", input)
	}
	quoted := byte(0)
	escaped := false
	end := -1
	for i := start + 2; i < len(input)-1; i++ {
		c := input[i]
		if quoted != 0 {
			if escaped {
				escaped = false
			} else if c == '\\' && quoted == '"' {
				escaped = true
			} else if c == quoted {
				quoted = 0
			}
			continue
		}
		if c == '"' || c == '`' {
			quoted = c
			continue
		}
		if c == '}' && input[i+1] == '}' {
			end = i
			break
		}
		if c == '{' || c == '}' {
			break
		}
	}
	if end < 0 || strings.ContainsAny(input[end+2:], "{}") {
		return "", "", "", false, trace.BadParameter("malformed template usage %q: expected {{expression}}", input)
	}
	return input[:start], strings.TrimSpace(input[start+2 : end]), input[end+2:], true, nil
}

func NewExpression(input string) (*Expression, error) {
	prefix, body, suffix, braced, err := splitTemplate(input)
	if err != nil {
		return nil, err
	}
	if !braced {
		return &Expression{expr: StringLitExpr{Value: body}}, nil
	}
	expr, err := parse(body)
	if err != nil {
		return nil, trace.BadParameter("invalid expression %q: %v", input, err)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q must evaluate to a string", input)
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.Wrap(err)
	}
	return &Expression{expr: expr, prefix: prefix, suffix: suffix}, nil
}

// Matcher matches an input string.
type Matcher interface{ Match(string) bool }
type MatcherFn func(string) bool

func (fn MatcherFn) Match(in string) bool { return fn(in) }
func NewAnyMatcher(in []string) (Matcher, error) {
	matchers := make([]Matcher, 0, len(in))
	for _, v := range in {
		m, err := NewMatcher(v)
		if err != nil {
			return nil, err
		}
		matchers = append(matchers, m)
	}
	return MatcherFn(func(s string) bool {
		for _, m := range matchers {
			if m.Match(s) {
				return true
			}
		}
		return false
	}), nil
}

// MatchExpression applies a boolean expression to the input between static text.
type MatchExpression struct {
	prefix, suffix string
	expr           Expr
}

func (m *MatchExpression) Match(in string) bool {
	if !strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) || len(in) < len(m.prefix)+len(m.suffix) {
		return false
	}
	middle := in[len(m.prefix) : len(in)-len(m.suffix)]
	v, err := m.expr.Evaluate(EvaluateContext{MatcherInput: middle})
	return err == nil && v == true
}
func NewMatcher(input string) (Matcher, error) {
	prefix, body, suffix, braced, err := splitTemplate(input)
	if err != nil {
		return nil, err
	}
	if !braced {
		pattern := body
		if !strings.HasPrefix(body, "^") || !strings.HasSuffix(body, "$") {
			pattern = "^" + utils.GlobToRegexp(body) + "$"
		}
		re, err := compileRegexp(pattern)
		if err != nil {
			return nil, err
		}
		return &MatchExpression{expr: RegexpMatchExpr{Pattern: pattern, re: re}}, nil
	}
	expr, err := parse(body)
	if err != nil {
		return nil, trace.BadParameter("invalid matcher %q: %v", input, err)
	}
	if expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("matcher %q must evaluate to a boolean", input)
	}
	return &MatchExpression{prefix: prefix, suffix: suffix, expr: expr}, nil
}

// parse creates typed nodes using the shared predicate parser.
func parse(exprStr string) (Expr, error) {
	if err := checkExpressionSize(exprStr); err != nil {
		return nil, err
	}
	p, err := predicate.NewParser(predicate.Def{Functions: map[string]interface{}{
		"email.local": func(args ...interface{}) (Expr, error) {
			if err := checkArity("email.local", args, 1); err != nil {
				return nil, err
			}
			e, err := stringArg(args[0], "email.local")
			if err != nil {
				return nil, err
			}
			return EmailLocalExpr{Input: e}, nil
		},
		"regexp.replace": func(args ...interface{}) (Expr, error) {
			if err := checkArity("regexp.replace", args, 3); err != nil {
				return nil, err
			}
			source, err := stringArg(args[0], "regexp.replace")
			if err != nil {
				return nil, err
			}
			pattern, ok := args[1].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.replace pattern must be a constant string")
			}
			replacement, ok := args[2].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.replace replacement must be a constant string")
			}
			re, err := compileRegexp(pattern)
			if err != nil {
				return nil, err
			}
			return RegexpReplaceExpr{Input: source, Pattern: pattern, Replacement: replacement, re: re}, nil
		},
		"regexp.match": func(args ...interface{}) (Expr, error) {
			if err := checkArity("regexp.match", args, 1); err != nil {
				return nil, err
			}
			pattern, ok := args[0].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.match pattern must be a constant string")
			}
			re, err := compileRegexp(pattern)
			if err != nil {
				return nil, err
			}
			return RegexpMatchExpr{Pattern: pattern, re: re}, nil
		},
		"regexp.not_match": func(args ...interface{}) (Expr, error) {
			if err := checkArity("regexp.not_match", args, 1); err != nil {
				return nil, err
			}
			pattern, ok := args[0].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.not_match pattern must be a constant string")
			}
			re, err := compileRegexp(pattern)
			if err != nil {
				return nil, err
			}
			return RegexpNotMatchExpr{Pattern: pattern, re: re}, nil
		},
	}, GetIdentifier: buildVarExpr, GetProperty: buildVarExprFromProperty})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	value, err := p.Parse(exprStr)
	if err != nil {
		return nil, trace.BadParameter("%v", err)
	}
	expr, ok := value.(Expr)
	if !ok {
		return nil, trace.BadParameter("expected namespace.name or function call, got %q", exprStr)
	}
	if err := validateExpr(expr); err != nil {
		return nil, err
	}
	return expr, nil
}
func checkArity(name string, args []interface{}, want int) error {
	if len(args) != want {
		return trace.BadParameter("%s expects %d arguments, got %d", name, want, len(args))
	}
	return nil
}
func stringArg(v interface{}, function string) (Expr, error) {
	if e, ok := v.(Expr); ok {
		if e.Kind() != reflect.String {
			return nil, trace.BadParameter("%s requires a string expression", function)
		}
		return e, nil
	}
	if s, ok := v.(string); ok {
		return StringLitExpr{Value: s}, nil
	}
	return nil, trace.BadParameter("%s requires a string expression", function)
}
func buildVarExpr(parts []string) (interface{}, error) {
	if len(parts) == 1 {
		switch parts[0] {
		case "internal", "external", "literal":
			return VarExpr{Namespace: parts[0]}, nil
		}
		return nil, trace.BadParameter("variable %q must have exactly two parts: namespace.name", strings.Join(parts, "."))
	}
	if len(parts) != 2 {
		return nil, trace.BadParameter("variable %q must have exactly two parts: namespace.name", strings.Join(parts, "."))
	}
	switch parts[0] {
	case "internal", "external", "literal":
	default:
		return nil, trace.BadParameter("unsupported namespace %q", parts[0])
	}
	return VarExpr{Namespace: parts[0], Name: parts[1]}, nil
}
func buildVarExprFromProperty(base, key interface{}) (interface{}, error) {
	v, ok := base.(VarExpr)
	if !ok || v.Name != "" {
		return nil, trace.BadParameter("expected exactly namespace[\"name\"]")
	}
	name, ok := key.(string)
	if !ok || name == "" {
		return nil, trace.BadParameter("expected exactly namespace[\"name\"]")
	}
	return VarExpr{Namespace: v.Namespace, Name: name}, nil
}
func checkExpressionSize(s string) error {
	if len(s) > 16384 {
		return trace.BadParameter("expression exceeds maximum length")
	}
	depth := 0
	quoted := byte(0)
	escaped := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quoted != 0 {
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == quoted {
				quoted = 0
			}
			continue
		}
		if c == '"' || c == '`' {
			quoted = c
			continue
		}
		if c == '(' || c == '[' {
			depth++
			if depth > 100 {
				return trace.BadParameter("expression exceeds maximum depth")
			}
		} else if c == ')' || c == ']' {
			depth--
		}
	}
	return nil
}

